mapper.select:

  select board_id, member_id, title, content, created_at, view_count
	from ( select rownum , board_id, member_id, title, content, created_at, view_count
			 from ( select row_number() over(order by board_id desc) as rownum
						 , board_id, member_id, title, content, created_at, view_count
					  from board_tb
					 order by board_id desc
					) a
			where rownum <= (#{pageNum} * #{amount})
		) aa
	where rownum > (#{pageNum}-1) * #{amount}
